	@Test
	public void modifyingThePriceRestartsTheTimer()
	{
		SlotTimer t = place(1000);
		t = SlotTimer.update(t, WHIP, true, 1_600_000, 10, 2, false, true, 5000);
		assertEquals("0:10", t.elapsed(5010, false));
